#define MAX_STEPS 128
#define HIT_THRESHOLD 0.0001

// Animation parameters.
#define sphereY iFloat0
#define sphereRadius iFloat1

// Representation of a surface. You might want to add other parameters. (reflectivity?)
struct Surface {
	vec3 color;
};

// The output of ray marching algorithm.
struct SceneDistance {
    float d;
    Surface surface;
};

// Signed distance to a plane, with normal n and offset d.
SceneDistance planeDist(Surface surface, vec3 p, vec3 n, float d) {
    return SceneDistance(
        dot(p, n.xyz) + d,
        surface
    );
}

// Signed distance from p to a sphere of radius r centred at the origin.
SceneDistance sphereDist(Surface surface, vec3 p, float r) {
    return SceneDistance(
        length(p) - r,
        surface
    );
}

// Signed distance from p to a box centred at the origin, with half-widths b.
SceneDistance boxDist(Surface surface, vec3 p, vec3 b) {
    vec3 q = abs(p) - b;
    return SceneDistance(
        length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0),
        surface
    );
}

// Signed distance from p to a torus lying flat round the origin: R to the middle of the tube, r its radius.
SceneDistance torusDist(Surface surface, vec3 p, float R, float r) {
    vec2 q = vec2(length(p.xz) - R, p.y);
    return SceneDistance(
        length(q) - r,
        surface
    );
}

// Union of two objects.
SceneDistance distanceUnion(SceneDistance d1, SceneDistance d2) {
    if (d1.d < d2.d) {
        return d1;
    }
    return d2;
}

vec3 translate(vec3 v, vec3 t) {
	return v - t;
}

// Rotate point by angle around axis, with the right-hand rule.
vec3 rotate(vec3 point, vec3 axis, float angle){
    axis = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float oc = 1.0 - c;
    // GLSL matrices are filled a column at a time, so each line here is a column.
    mat3 rot = mat3(
        oc * axis.x * axis.x + c, oc * axis.x * axis.y + axis.z * s, oc * axis.z * axis.x - axis.y * s,
        oc * axis.x * axis.y - axis.z * s, oc * axis.y * axis.y + c, oc * axis.y * axis.z + axis.x * s,
        oc * axis.z * axis.x + axis.y * s, oc * axis.y * axis.z - axis.x * s, oc * axis.z * axis.z + c);
    return rot * point;
}


SceneDistance scene(in vec3 pos) {
  Surface surf1 = Surface(vec3(0.654, 0.270, 1.000));
  Surface surf2 = Surface(vec3(1.000, 0.286, 0.421));
  Surface surf3 = Surface(vec3(1.000, 0.780, 0.250));
  Surface surf4 = Surface(vec3(0.300, 0.850, 0.900));

	SceneDistance sphere = sphereDist(
        surf2, translate( pos, vec3(0., sphereY, 0.)), sphereRadius ); 

	SceneDistance ground = planeDist(
        surf1, pos, vec3(0., 1., 0.), 0.);

	// Turning the point one way turns the object the other, once round over the animation.
	float spin = 6.2831853 * iTime / iDuration;
	SceneDistance box = boxDist(
        surf3, rotate(translate(pos, vec3(-2.3, 0.6, -0.8)), vec3(0., 1., 0.), -spin), vec3(0.6));

	SceneDistance torus = torusDist(
        surf4, rotate(translate(pos, vec3(2.3, 0.95, -0.8)), vec3(1., 0., 0.), -spin), 0.6, 0.25);

	return distanceUnion(distanceUnion(ground, sphere), distanceUnion(box, torus));
}

vec3 sceneNormal(vec3 pos, float d) {
    float eps = 0.001;
    vec3 n;

    n.x = scene(vec3( pos.x + eps, pos.y, pos.z )).d - d;
    n.y = scene(vec3( pos.x, pos.y + eps, pos.z )).d - d;
    n.z = scene(vec3( pos.x, pos.y, pos.z + eps )).d - d;

    return normalize(n);
}

struct Ray {
	vec3 org;
	vec3 dir;
};

struct MarchResult {
	bool hit;
    vec3 pos;
    vec3 norm;
    int steps;
    Surface surface;
};

MarchResult rayMarch(Ray ray) {
	MarchResult result = MarchResult(
    	false,
        ray.org,
        vec3(0., 0., 0.),
        0,
        Surface(vec3(0., 0., 0.))
    );

    for (; result.steps < MAX_STEPS; result.steps++) {
		SceneDistance sd = scene(result.pos);
		if (abs(sd.d) < HIT_THRESHOLD) {
			result.hit = true;
			result.norm = sceneNormal(result.pos, sd.d);
            result.surface = sd.surface;
			break;
		}
		result.pos += sd.d * ray.dir;
	}
	return result;
}


float shadow(vec3 ro, vec3 rd, float mint, float maxt) {
	float t = mint;
    for ( int i = 0; i < 64; ++i )
    {
        float h = scene(ro + rd * t).d;
        if ( h < 0.001 && i > 0) {
            return 0.2;
        }
        t += h;

		if ( t > maxt )
			break;
    }
    return 1.0;
}


vec3 shade(MarchResult marchResult, vec4 light) {
	vec3 toLight = light.xyz - marchResult.pos;
	float toLightLen = length(toLight);
	toLight = normalize(toLight);
	float vis = shadow(marchResult.pos, toLight, 0.01, toLightLen);
  float diff = 2. * max(0.0, dot(marchResult.norm, toLight));
  float attn = 1.0 - pow(min(1.0, toLightLen / light.w), 2.0);
	float mask = (.2 + diff * attn) *  vis;
	return mask * marchResult.surface.color;
}


void mainImage(out vec4 fragColor, in vec2 fragCoord) {
	float aspectRatio = iResolution.x / iResolution.y;

  Ray ray;
  ray.org = vec3(0.0, 3.2, 7.0);
  vec4 light = vec4(-2., 3., 2., 10.);
  float t = 4. * 3.14159 * iTime / iDuration;
  light.x += cos(t);
  light.y += sin(t);


  vec2 ndcXY = -1.0 + 2.0 * (
    fragCoord.xy) / iResolution.xy;
  vec2 scaledXY = .5 * ndcXY * vec2( aspectRatio, 1.0 );


  ray.dir =  normalize(vec3( scaledXY, -1 ));
  // Tilt the camera to look down a little.
  ray.dir = rotate(ray.dir, vec3(1., 0., 0.), -0.33);


  MarchResult marchResult = rayMarch(ray);
  vec3 col = vec3(0.0);
  if (marchResult.hit) {

    col = .4 * shade(marchResult, light);
  }

  fragColor = vec4(col, 1.0);

}
